-- XAMPP MySQL / MariaDB. All monetary amounts are integer centavos.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS tenants (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, email VARCHAR(254) NOT NULL, contact VARCHAR(80) NOT NULL, status ENUM('active','moved_out') NOT NULL DEFAULT 'active', move_in DATE NOT NULL, move_out DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','staff','tenant') NOT NULL, name VARCHAR(200) NOT NULL, tenant_id INT UNSIGNED UNIQUE NULL, active TINYINT DEFAULT 1, must_change TINYINT DEFAULT 1, FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number VARCHAR(50) UNIQUE NOT NULL, capacity INT NOT NULL CHECK(capacity BETWEEN 1 AND 30), rent BIGINT NOT NULL CHECK(rent>=0), status ENUM('active','maintenance') DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bed_spaces (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_id INT UNSIGNED NOT NULL, label VARCHAR(50) NOT NULL, UNIQUE(room_id,label), FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tenant_assignments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, bed_id INT UNSIGNED NOT NULL, start_date DATE NOT NULL, end_date DATE NULL, active_bed INT UNSIGNED GENERATED ALWAYS AS (CASE WHEN end_date IS NULL THEN bed_id ELSE NULL END) STORED UNIQUE, active_tenant INT UNSIGNED GENERATED ALWAYS AS (CASE WHEN end_date IS NULL THEN tenant_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(bed_id) REFERENCES bed_spaces(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS billing (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, assignment_id INT UNSIGNED NOT NULL, period CHAR(7) NOT NULL, cutoff DATE NOT NULL, due_date DATE NOT NULL, rent BIGINT NOT NULL CHECK(rent>=0), electricity BIGINT NOT NULL CHECK(electricity>=0), water BIGINT NOT NULL CHECK(water>=0), previous_balance BIGINT NOT NULL DEFAULT 0 CHECK(previous_balance>=0), total_due BIGINT NOT NULL CHECK(total_due>=0), carried_to INT UNSIGNED NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,period), KEY(due_date), FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(assignment_id) REFERENCES tenant_assignments(id), FOREIGN KEY(carried_to) REFERENCES billing(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS billing_adjustments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, billing_id INT UNSIGNED NOT NULL, type ENUM('discount','adjustment') NOT NULL, amount BIGINT NOT NULL, reason TEXT NOT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(billing_id) REFERENCES billing(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS utility_charges (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, billing_id INT UNSIGNED NOT NULL, type ENUM('water','electricity') NOT NULL, amount BIGINT NOT NULL CHECK(amount>=0), UNIQUE(billing_id,type), FOREIGN KEY(billing_id) REFERENCES billing(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, billing_id INT UNSIGNED NOT NULL, tenant_id INT UNSIGNED NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), method ENUM('GCash','Personal Payment') NOT NULL, payer VARCHAR(200) NOT NULL, payment_date DATE NOT NULL, reference VARCHAR(150) NULL, received_by INT UNSIGNED NOT NULL, idempotency_key VARCHAR(100) UNIQUE NOT NULL, balance_after BIGINT NULL, voided_at DATETIME NULL, voided_by INT UNSIGNED NULL, void_reason TEXT NULL, gcash_reference VARCHAR(150) GENERATED ALWAYS AS (CASE WHEN method='GCash' THEN reference ELSE NULL END) STORED UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY(payment_date), FOREIGN KEY(billing_id) REFERENCES billing(id), FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(received_by) REFERENCES users(id), FOREIGN KEY(voided_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS deposits (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), received_date DATE NOT NULL, refund_amount BIGINT NULL CHECK(refund_amount>=0 AND refund_amount<=amount), deduction_reason TEXT NULL, refunded_date DATE NULL, recorded_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(recorded_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS occupancy_scans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_id INT UNSIGNED NOT NULL, detected_count INT NOT NULL CHECK(detected_count>=0), registered_count INT NOT NULL, capacity INT NOT NULL, source ENUM('manual','camera') NOT NULL, notes TEXT NULL, scanned_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(room_id) REFERENCES rooms(id), FOREIGN KEY(scanned_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, billing_id INT UNSIGNED NULL, type VARCHAR(30) NOT NULL, email VARCHAR(254) NOT NULL, subject VARCHAR(255) NOT NULL, message TEXT NOT NULL, status ENUM('queued','sent','failed') DEFAULT 'queued', error TEXT NULL, sent_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, dedup_key VARCHAR(150) UNIQUE NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(billing_id) REFERENCES billing(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(255) NOT NULL, record_type VARCHAR(80) NULL, record_id INT UNSIGNED NULL, details TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identity CHAR(64) NOT NULL, attempted_at BIGINT NOT NULL, KEY(identity,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vendor VARCHAR(200) NOT NULL DEFAULT '', payment_method ENUM('Cash','GCash','Bank transfer') NOT NULL DEFAULT 'Cash', idempotency_key VARCHAR(100) UNIQUE NULL, voided_at DATETIME NULL, voided_by INT UNSIGNED NULL, void_reason VARCHAR(1000) NULL, category ENUM('Utilities','Maintenance','Supplies','Salaries','Other') NOT NULL, description VARCHAR(255) NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), expense_date DATE NOT NULL, reference VARCHAR(150) NULL, recorded_by INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(recorded_by) REFERENCES users(id), CONSTRAINT fk_expense_voider FOREIGN KEY(voided_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS maintenance_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, room_id INT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, priority ENUM('normal','urgent') DEFAULT 'normal', status ENUM('open','in_progress','resolved') DEFAULT 'open', admin_note TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS announcements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, expires_on DATE NULL, active TINYINT DEFAULT 1, created_by INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_submissions (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, billing_id INT UNSIGNED NOT NULL,
 amount BIGINT NOT NULL CHECK(amount>0), payer VARCHAR(200) NOT NULL, payment_date DATE NOT NULL,
 reference VARCHAR(150) NOT NULL, proof_file VARCHAR(100) NULL, notes TEXT NULL,
 status ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',
 active_reference VARCHAR(150) GENERATED ALWAYS AS (CASE WHEN status IN ('pending','approved') THEN reference ELSE NULL END) STORED UNIQUE,
 submission_key VARCHAR(100) UNIQUE NOT NULL, payment_id INT UNSIGNED NULL UNIQUE,
 reviewed_by INT UNSIGNED NULL, review_note TEXT NULL, reviewed_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(billing_id) REFERENCES billing(id),
 FOREIGN KEY(payment_id) REFERENCES payments(id), FOREIGN KEY(reviewed_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tenant_inquiries (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL,
 category ENUM('Billing','Payment','Room assignment','Deposit','Other') NOT NULL,
 subject VARCHAR(200) NOT NULL, message TEXT NOT NULL,
 status ENUM('open','resolved') NOT NULL DEFAULT 'open', reply TEXT NULL,
 replied_by INT UNSIGNED NULL, replied_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(replied_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
